# Validation regression suite for ClinicoPath::jjwithinstats
# Generated by /validate-function jjwithinstats depth=exhaustive (2026-11-18).
# Live tests lock in verified PASS claims; skip-guarded tests assert the correct
# expected behavior for confirmed open defects VAL-jjwithinstats-01 through VAL-jjwithinstats-11.

library(testthat)

jw_val_strip_html <- function(h) trimws(gsub("\\s+", " ", gsub("<[^>]+>", " ", as.character(h))))

jw_val_render_main <- function(data, ...) {
  opts <- do.call(ClinicoPath:::jjwithinstatsOptions$new, list(...))
  a    <- ClinicoPath:::jjwithinstatsClass$new(options = opts, data = data)
  suppressWarnings(suppressMessages(a$run()))
  tf <- tempfile(fileext = ".png")
  grDevices::png(tf, width = 700, height = 500, res = 96)
  on.exit({
    try(grDevices::dev.off(), silent = TRUE)
    unlink(tf)
  }, add = TRUE)
  suppressWarnings(suppressMessages(
    a$.__enclos_env__$private$.plot(a$results$plot, ggtheme = ggplot2::theme_bw(), theme = NULL)
  ))
  ggplot2::last_plot()
}

jw_val_render_ggpubr <- function(data, ...) {
  opts <- do.call(ClinicoPath:::jjwithinstatsOptions$new, list(...))
  a    <- ClinicoPath:::jjwithinstatsClass$new(options = opts, data = data)
  suppressWarnings(suppressMessages(a$run()))
  tf <- tempfile(fileext = ".png")
  grDevices::png(tf, width = 700, height = 500, res = 96)
  on.exit({
    try(grDevices::dev.off(), silent = TRUE)
    unlink(tf)
  }, add = TRUE)
  ret <- suppressWarnings(suppressMessages(
    a$.__enclos_env__$private$.plotGGPubr(a$results$ggpubrPlot, ggtheme = ggplot2::theme_bw(), theme = NULL)
  ))
  list(analysis = a, ret = ret, plot = if (isTRUE(ret)) ggplot2::last_plot() else NULL)
}

jw_val_eq_nums <- function(expr_obj) {
  s <- paste(deparse(expr_obj), collapse = " ")
  m <- gregexpr('==\\s*"([^"]+)"', s, perl = TRUE)
  raw <- regmatches(s, m)[[1]]
  as.numeric(sub('^==\\s*"([^"]+)"$', "\\1", raw, perl = TRUE))
}

test_that("C01-C05: pairedChanges contrasts, labels, complete-case N, units, and mean paired change match exact hand arithmetic", {
  # Oracle: closed-form sample mean on 8 complete pairs (d = 2,-1,0,4,6,3,8,10 -> sum=32, mean=4.0)
  d <- data.frame(
    Pre  = c(10, 12, 15, 18, 20, 22, 25, 30, 14),
    Post = c(12, 11, 15, 22, 26, 25, 33, 40, NA_real_)
  )
  res <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d, dep1 = "Pre", dep2 = "Post", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedEstimator = "mean", pairedCIMethod = "standard",
    pairedUnits = "mm", pairedTimeRatios = TRUE
  ))
  tb <- res$pairedChanges$asDF
  expect_equal(tb$contrast, c("Post \u2212 Pre", "Post / Pre"))
  expect_equal(tb$effect, c("Mean paired change", "Geometric mean paired time ratio"))
  expect_equal(tb$pairs, c(8L, 8L))
  expect_equal(tb$units, c("mm", "ratio"))
  expect_equal(tb$estimate[1], 4.0, tolerance = 1e-12)
})

