})

test_that("C07 & C09: pairedChanges Hodges-Lehmann shift and signed-rank normal-approximation interval match Walsh median and wilcox.test", {
  # Oracle: Hodges & Lehmann (1963, Ann Math Stat 34:598-611) median Walsh average; stats::wilcox.test(exact=FALSE, correct=TRUE)
  skip_if_not_installed("DescTools")
  d_vec <- c(-2.2, -1.7, -0.1, 0.8, 1.4, 2.1, 2.9, 3.7, 4.6, 5.2,
             5.9, 6.8, 7.3, 8.1, 9.6, 10.4, 12.7, 14.1, 15.3, 18.7)
  d <- data.frame(Pre = rep(30, 20), Post = 30 + d_vec)
  walsh <- outer(d_vec, d_vec, "+") / 2
  hl_ref <- stats::median(walsh[upper.tri(walsh, diag = TRUE)])
  wt_ref <- stats::wilcox.test(d_vec, conf.int = TRUE, exact = FALSE, correct = TRUE)

  res <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d, dep1 = "Pre", dep2 = "Post", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedEstimator = "hodges_lehmann", pairedCIMethod = "standard"
  ))
  tb <- res$pairedChanges$asDF
  expect_equal(tb$estimate[1], hl_ref, tolerance = 1e-10)
  expect_equal(c(tb$lower[1], tb$upper[1]), as.numeric(wt_ref$conf.int), tolerance = 1e-8)
})

test_that("C08: pairedChanges Student t interval matches Cushny-Peebles / Student (1908) canonical sleep dataset and nests monotonically", {
  # Oracle: Student (1908, Biometrika 6:1-25) / stats::t.test(extra.2, extra.1, paired = TRUE)
  data(sleep, package = "datasets")
  sleep_w <- stats::reshape(sleep, idvar = "ID", timevar = "group", direction = "wide")
  ref_t   <- stats::t.test(sleep_w$extra.2, sleep_w$extra.1, paired = TRUE)
  res     <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = sleep_w, dep1 = "extra.1", dep2 = "extra.2", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedEstimator = "mean", pairedCIMethod = "standard", conflevel = 0.95
  ))
  tb <- res$pairedChanges$asDF
  expect_equal(tb$estimate[1], unname(ref_t$estimate), tolerance = 1e-12)
  expect_equal(c(tb$lower[1], tb$upper[1]), as.numeric(ref_t$conf.int), tolerance = 1e-12)
  expect_equal(tb$p[1], ref_t$p.value, tolerance = 1e-12)
})

test_that("C10: pairedChanges bootstrap interval is row-order invariant, preserves caller RNG, and recovers exact n=3 discrete grid", {
  # Oracle: exact enumeration of all 3^3 = 27 bootstrap resamples on diffs (0, 3, 6) -> 80% quantiles = (1, 5)
  d3 <- data.frame(a = c(10, 20, 30), b = c(10, 23, 36))
  set.seed(777)
  old_seed <- .Random.seed
  res1 <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d3, dep1 = "a", dep2 = "b", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedEstimator = "mean", pairedCIMethod = "bootstrap",
    pairedBootstrap = 10000, conflevel = 0.80, seed = 20250101
  ))
  expect_identical(.Random.seed, old_seed)
  res2 <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d3[c(3, 1, 2), ], dep1 = "a", dep2 = "b", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedEstimator = "mean", pairedCIMethod = "bootstrap",
    pairedBootstrap = 10000, conflevel = 0.80, seed = 20250101
  ))
  expect_equal(c(res1$pairedChanges$asDF$lower[1], res1$pairedChanges$asDF$upper[1]), c(1, 5), tolerance = 1e-12)
  expect_equal(res1$pairedChanges$asDF$lower[1], res2$pairedChanges$asDF$lower[1], tolerance = 1e-12)
  expect_equal(res1$pairedChanges$asDF$upper[1], res2$pairedChanges$asDF$upper[1], tolerance = 1e-12)
})

test_that("C10 (VAL-jjwithinstats-05 / IR-05): default pairedCIMethod achieves nominal 95% coverage for mean at small clinical n=8", {
  # Oracle: nominal 95% coverage (+/- 3 MC SE = 0.0207 at R=1000) under Gaussian paired differences at n=8
  set.seed(20261118)
  R <- 1000L
  covered <- logical(R)
  for (b in seq_len(R)) {
    s <- stats::rnorm(8, 20, 4)
    d <- data.frame(pre = s + stats::rnorm(8, 0, 1), post = s + stats::rnorm(8, 2, 1))
    tb <- suppressWarnings(ClinicoPath::jjwithinstats(
      data = d, dep1 = "pre", dep2 = "post", dep3 = NULL, dep4 = NULL,
      pairedEffects = TRUE, pairedEstimator = "mean"
    ))$pairedChanges$asDF
    covered[b] <- (tb$lower[1] <= 2) && (2 <= tb$upper[1])
  }
  expect_gte(mean(covered), 0.95 - 3 * sqrt(0.95 * 0.05 / R))
})

test_that("C11 & C12: geometric mean paired time ratio matches exp(mean(log(y2/y1))), inverts on swap, and withholds on zeros without dropping pairs", {
  # Oracle: closed-form exp(mean(log(Post) - log(Pre))) and log-scale Student t interval
  d <- data.frame(Pre = c(2, 4, 10, 20, 25), Post = c(4, 6, 15, 30, 50))
  lr <- log(d$Post) - log(d$Pre)
  res <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d, dep1 = "Pre", dep2 = "Post", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedCIMethod = "standard", pairedTimeRatios = TRUE
  ))
  tb <- res$pairedChanges$asDF
  expect_equal(tb$estimate[2], exp(mean(lr)), tolerance = 1e-12)
  expect_equal(c(tb$lower[2], tb$upper[2]), exp(as.numeric(stats::t.test(lr)$conf.int)), tolerance = 1e-12)

  res_swap <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d, dep1 = "Post", dep2 = "Pre", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedCIMethod = "standard", pairedTimeRatios = TRUE
  ))$pairedChanges$asDF
  expect_equal(res_swap$estimate[2], 1 / tb$estimate[2], tolerance = 1e-12)

  d_zero <- d; d_zero$Pre[1] <- 0
  tb_zero <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d_zero, dep1 = "Pre", dep2 = "Post", dep3 = NULL, dep4 = NULL,
    pairedEffects = TRUE, pairedCIMethod = "standard", pairedTimeRatios = TRUE
  ))$pairedChanges$asDF
  expect_equal(tb_zero$pairs, c(5L, 5L))
  expect_true(is.na(tb_zero$estimate[2]))
  expect_match(tb_zero$note[2], "strictly positive")
})

test_that("C13 & C14: pairedChanges p-values match Conover (1999) Durbin-Conover and stats::p.adjust across all multiplicity methods", {
  # Oracle: Conover (1999, Practical Nonparametric Statistics 3rd ed., sec. 5.8) exact rank-sum t formula
  set.seed(101)
  x1 <- stats::rnorm(20, 50, 10); x2 <- x1 + stats::rnorm(20, 5, 4); x3 <- x1 + stats::rnorm(20, 10, 5)
  d3 <- data.frame(T1 = x1, T2 = x2, T3 = x3)
  R_mat <- t(apply(as.matrix(d3), 1, rank))
  R_sum <- colSums(R_mat)
  denom <- sqrt((2 * (20 * sum(R_mat^2) - sum(R_sum^2))) / (19 * 2))
  t_dc  <- c(abs(R_sum[2] - R_sum[1]), abs(R_sum[3] - R_sum[1]), abs(R_sum[3] - R_sum[2])) / denom
  p_dc_holm <- stats::p.adjust(2 * stats::pt(-t_dc, df = 38), method = "holm")

  res_np <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d3, dep1 = "T1", dep2 = "T2", dep3 = "T3", dep4 = NULL,
    typestatistics = "nonparametric", pairwisecomparisons = TRUE, padjustmethod = "holm",
    pairedEffects = TRUE, pairedCIMethod = "standard"
  ))$pairedChanges$asDF
  expect_equal(res_np$p, unname(p_dc_holm), tolerance = 1e-8)
  expect_true(all(res_np$test == "Durbin-Conover"))
})

