  # Oracle: exact d_z = mean(d)/sd(d), Hedges (1981) gamma factor, and Kerby (2014, DOI:10.2466/11.IT.3.1) r_rb = (W+ - W-)/28 = -13/14
  skip_if_not_installed("ggstatsplot")
  skip_if_not_installed("statsExpressions")
