    Pre  = c(10, 12, 15, 18, 20, 22, 25, 30),
    Post = c(12, 11, 15, 22, 26, 25, 33, 40)
  )
  dz <- -4 / sqrt(102 / 7)
  gz <- dz * exp(lgamma(7 / 2) - 0.5 * log(7 / 2) - lgamma(3))

  p_d <- jw_val_render_main(d, dep1 = "Pre", dep2 = "Post", typestatistics = "parametric",
                            effsizetype = "biased", resultssubtitle = TRUE, k = 5)
  p_g <- jw_val_render_main(d, dep1 = "Pre", dep2 = "Post", typestatistics = "parametric",
