                            resultssubtitle = TRUE, k = 5)
  expect_equal(jw_val_eq_nums(p_d$labels$subtitle)[3], round(dz, 5), tolerance = 1e-5)
  expect_equal(jw_val_eq_nums(p_g$labels$subtitle)[3], round(gz, 5), tolerance = 1e-5)
