test_that("C16: main plot 3-measurement subtitle matches Greenhouse-Geisser (1959) epsilon, F, partial eta^2, and Olejnik-Algina (2003) partial omega^2", {
  # Oracle: Greenhouse & Geisser (1959, DOI:10.1007/BF02289823) orthonormal Helmert contrast covariance; Olejnik & Algina (2003, DOI:10.1037/1082-989X.8.4.434)
  skip_if_not_installed("ggstatsplot")
  skip_if_not_installed("afex")
  set.seed(101)
  x1 <- stats::rnorm(20, 50, 10); x2 <- x1 + stats::rnorm(20, 5, 4); x3 <- x1 + stats::rnorm(20, 10, 5)
  d3 <- data.frame(T1 = x1, T2 = x2, T3 = x3)
  C_orth <- qr.Q(qr(stats::contr.helmert(3)))
  S_star <- crossprod(C_orth, stats::cov(as.matrix(d3))) %*% C_orth
  eps_gg <- (sum(diag(S_star))^2) / (2 * sum(S_star^2))

  long <- data.frame(id = factor(rep(1:20, 3)), tm = factor(rep(c("T1", "T2", "T3"), each = 20)), y = c(x1, x2, x3))
  s_aov <- summary(stats::aov(y ~ tm + Error(id / tm), data = long))
  ss_id <- s_aov[[1]][[1]]["Residuals", "Sum Sq"]; ms_id <- s_aov[[1]][[1]]["Residuals", "Mean Sq"]
  ss_tm <- s_aov[[2]][[1]]["tm", "Sum Sq"];        ms_tm <- s_aov[[2]][[1]]["tm", "Mean Sq"]
  ss_er <- s_aov[[2]][[1]]["Residuals", "Sum Sq"]; ms_er <- s_aov[[2]][[1]]["Residuals", "Mean Sq"]
  eta2_p <- ss_tm / (ss_tm + ss_er)
  om2_oa <- (2 * (ms_tm - ms_er)) / (ss_tm + ss_er + ss_id + ms_id)

  p_eta <- jw_val_render_main(d3, dep1 = "T1", dep2 = "T2", dep3 = "T3", effsizetype = "eta", resultssubtitle = TRUE, k = 5)
  p_om  <- jw_val_render_main(d3, dep1 = "T1", dep2 = "T2", dep3 = "T3", effsizetype = "omega", resultssubtitle = TRUE, k = 5)
  expect_equal(jw_val_eq_nums(p_eta$labels$subtitle)[1], round(ms_tm / ms_er, 5), tolerance = 1e-5)
  expect_equal(jw_val_eq_nums(p_eta$labels$subtitle)[3], round(eta2_p, 5), tolerance = 1e-5)
  expect_equal(jw_val_eq_nums(p_om$labels$subtitle)[3],  round(om2_oa, 5), tolerance = 1e-5)
  expect_match(paste(deparse(p_eta$labels$subtitle), collapse = " "), sprintf("%.5f", 2 * eps_gg), fixed = TRUE)
})

