test_that("C18: Friedman chi-square and Kendall W match exact closed-form rank sums", {
  # Oracle: Friedman (1937) chi^2 = (12/(nk(k+1)))*sum(R_j^2) - 3n(k+1); Kendall's W = chi^2/(n(k-1))
  set.seed(101)
  x1 <- stats::rnorm(20, 50, 10); x2 <- x1 + stats::rnorm(20, 5, 4); x3 <- x1 + stats::rnorm(20, 10, 5)
  d3 <- data.frame(T1 = x1, T2 = x2, T3 = x3)
  R_sum <- colSums(t(apply(as.matrix(d3), 1, rank)))
  chi2  <- (12 / (20 * 3 * 4)) * sum(R_sum^2) - 3 * 20 * 4
  w_ref <- chi2 / 40

  p_np3 <- jw_val_render_main(d3, dep1 = "T1", dep2 = "T2", dep3 = "T3",
                              typestatistics = "nonparametric", resultssubtitle = TRUE, k = 5)
  expect_equal(jw_val_eq_nums(p_np3$labels$subtitle)[c(1, 3)], c(round(chi2, 5), round(w_ref, 5)), tolerance = 1e-5)
})

