test_that("C19, C20 & C21: Yuen paired 20%-trimmed t-test and Rouder (2009) JZS Cauchy Bayes factor match independent base-R derivations", {
  # Oracle: Yuen (1974, DOI:10.1093/biomet/61.1.165) Winsorized covariance; Rouder et al. (2009, DOI:10.3758/PBR.16.2.225) JZS integral
  skip_if_not_installed("WRS2")
  skip_if_not_installed("BayesFactor")
  set.seed(101)
  x1 <- stats::rnorm(20, 50, 10); x2 <- x1 + stats::rnorm(20, 5, 4)
  d2 <- data.frame(T1 = x1, T2 = x2)
  g <- 4L; h <- 12L
  tm <- function(v) mean(sort(v)[(g + 1):(20 - g)])
  wn <- function(v) { sv <- sort(v); pmin(pmax(v, sv[g + 1]), sv[20 - g]) }
  w1 <- wn(x1); w2 <- wn(x2)
  t_yuen <- (tm(x1) - tm(x2)) / sqrt(19 * (stats::var(w1) + stats::var(w2) - 2 * stats::cov(w1, w2)) / (h * (h - 1)))

  t_obs <- as.numeric(stats::t.test(x1, x2, paired = TRUE)$statistic)
  marg  <- stats::integrate(function(del) stats::dt(t_obs, df = 19, ncp = sqrt(20) * del) * stats::dcauchy(del, 0, 0.707),
                            lower = -Inf, upper = Inf, rel.tol = 1e-11)$value
  log_bf01 <- -log(marg / stats::dt(t_obs, df = 19))

  p_rob <- jw_val_render_main(d2, dep1 = "T1", dep2 = "T2", typestatistics = "robust", resultssubtitle = TRUE, k = 5, seed = 20250101)
  p_bf  <- jw_val_render_main(d2, dep1 = "T1", dep2 = "T2", typestatistics = "bayes",  resultssubtitle = TRUE, k = 5, seed = 20250101)
  expect_equal(jw_val_eq_nums(p_rob$labels$subtitle)[1], round(t_yuen, 5), tolerance = 1e-5)
  expect_equal(jw_val_eq_nums(p_bf$labels$subtitle)[1],  round(log_bf01, 5), tolerance = 1e-4)
})

test_that("C23 & C24: centrality coordinates match exact sample summaries and ggpubr line preserves non-alphabetical measurement order", {
  # Oracle: exact sample mean, median, 20% trimmed mean, and mean +/- SE ordered by dep1..dep3
  skip_if_not_installed("ggpubr")
  set.seed(101)
  x1 <- stats::rnorm(20, 50, 10); x2 <- x1 + stats::rnorm(20, 5, 4); x3 <- x1 + stats::rnorm(20, 10, 5)
  d_na <- data.frame(Z_Pre = x1, M_Mid = x2, A_Post = x3)

  p_med <- jw_val_render_main(d_na, dep1 = "Z_Pre", dep2 = "M_Mid", centralityplotting = TRUE, centralitytype = "nonparametric")
  b_med <- ggplot2::ggplot_build(p_med)
  ct_df <- Filter(function(df) nrow(df) == 2L && "y" %in% names(df), b_med$data)[[1]]
  expect_equal(ct_df$y[order(ct_df$x)], c(stats::median(x1), stats::median(x2)), tolerance = 1e-8)

  gg_ln <- jw_val_render_ggpubr(d_na, dep1 = "Z_Pre", dep2 = "M_Mid", dep3 = "A_Post",
                                addGGPubrPlot = TRUE, ggpubrPlotType = "line")
  b_ln  <- ggplot2::ggplot_build(gg_ln$plot)
  eb_df <- Filter(function(df) all(c("ymin", "ymax") %in% names(df)) && nrow(df) == 3L, b_ln$data)[[1]]
  eb_df <- eb_df[order(eb_df$x), , drop = FALSE]
  means <- c(mean(x1), mean(x2), mean(x3))
  ses   <- c(stats::sd(x1), stats::sd(x2), stats::sd(x3)) / sqrt(20)
  expect_equal(c(eb_df$ymin, eb_df$ymax), c(means - ses, means + ses), tolerance = 1e-8)
})

test_that("C25 & C28 (VAL-jjwithinstats-01 / IR-01): jamovi integer-backed factors (permitted: [numeric]) render accurately in main plot and ggpubrPlot", {
  # Oracle: jmvcore::toNumeric() extracts integer 'values' attribute on Nominal/Ordinal jamovi columns
  skip_if_not_installed("ggpubr")
  mk_jmv <- function(vals, labs = NULL, codes = NULL) {
    uc <- if (is.null(codes)) sort(unique(vals)) else codes
    ul <- if (is.null(labs)) as.character(uc) else labs
    f  <- factor(ul[match(vals, uc)], levels = ul)
    attr(f, "values") <- as.integer(uc)
    f
  }
  d_txt <- data.frame(
    Pre  = mk_jmv(c(0, 1, 2, 1, 3, 0, 2, 1, 2, 3), paste("Grade", 0:3), 0:3),
    Post = mk_jmv(c(1, 2, 3, 2, 3, 1, 3, 2, 3, 3), paste("Grade", 0:3), 0:3)
  )
  r_txt <- ClinicoPath::jjwithinstats(data = d_txt, dep1 = "Pre", dep2 = "Post", dep3 = NULL, dep4 = NULL)
  tf <- tempfile(fileext = ".png"); on.exit(unlink(tf), add = TRUE)
  expect_no_error(r_txt$plot$saveAs(tf))

  d_num <- data.frame(
    Pre  = mk_jmv(c(0, 10, 20, 10, 100, 0, 20, 300, 10, 100)),
    Post = mk_jmv(c(10, 20, 100, 20, 200, 10, 100, 300, 20, 200))
  )
  gg_box <- jw_val_render_ggpubr(d_num, dep1 = "Pre", dep2 = "Post", addGGPubrPlot = TRUE, ggpubrPlotType = "boxplot")
  expect_equal(ggplot2::ggplot_build(gg_box$plot)$data[[1]]$middle, c(15, 60))
  gg_ln  <- jw_val_render_ggpubr(d_num, dep1 = "Pre", dep2 = "Post", addGGPubrPlot = TRUE, ggpubrPlotType = "line")
  expect_true(isTRUE(gg_ln$ret))
})

