test_that("C30: asSource() exported R syntax reproduces identical pairedChanges results with special/UTF-8 column names", {
  # Oracle: self-consistency of exported R code evaluated in a clean environment
  d <- data.frame(
    c1 = c(10, 12, 15, 18, 20, 22, 25, 30),
    c2 = c(12, 11, 15, 22, 26, 25, 33, 40)
  )
  names(d) <- c("CRP [mg/L] + 1", "Gr\u00e9ade sc (mm)")
  opts <- ClinicoPath:::jjwithinstatsOptions$new(
    dep1 = "CRP [mg/L] + 1", dep2 = "Gr\u00e9ade sc (mm)",
    pairedEffects = TRUE, pairedEstimator = "mean", pairedCIMethod = "standard", pairedTimeRatios = TRUE
  )
  a <- ClinicoPath:::jjwithinstatsClass$new(options = opts, data = d)
  suppressWarnings(a$run())
  env_eval <- new.env(parent = globalenv())
  env_eval$data <- d
  res_re <- suppressWarnings(eval(parse(text = a$asSource()), envir = env_eval))
  expect_equal(res_re$pairedChanges$asDF$estimate, a$results$pairedChanges$asDF$estimate, tolerance = 1e-12)
  expect_equal(res_re$pairedChanges$asDF$lower,    a$results$pairedChanges$asDF$lower,    tolerance = 1e-12)
  expect_equal(res_re$pairedChanges$asDF$upper,    a$results$pairedChanges$asDF$upper,    tolerance = 1e-12)
})

test_that("C32 (VAL-jjwithinstats-11 / IR-12): refs in jjwithinstats.r.yaml cite DescTools and omit unused haven", {
  # Oracle: R/jjwithinstats-paired-effects.R calls DescTools::HodgesLehmann(); haven:: is never called
  r_yaml <- readLines(testthat::test_path("..", "..", "jamovi", "jjwithinstats.r.yaml"), warn = FALSE)
  refs_b <- r_yaml[(grep("^refs:", r_yaml)[1] + 1L):length(r_yaml)]
  refs   <- trimws(sub("^\\s*-\\s*", "", grep("^\\s*-\\s*", refs_b, value = TRUE)))
  expect_true("DescTools" %in% refs)
  expect_false("haven" %in% refs)
})

test_that("IR-07, IR-08 & IR-10: preset guidance disclaimers, weightsSupport='none' protection, default independent-case scope, paired lines default, and wrapper claims", {
  d8 <- data.frame(Pre = c(10, 12, 15, 18, 20, 22, 25, 30), Post = c(12, 11, 15, 22, 26, 25, 33, 40))

  # IR-07: all non-custom presets explicitly state '(guidance only)' and name the active test
  for (pr in c("biomarker", "treatment", "laboratory")) {
    r_pr <- suppressWarnings(ClinicoPath::jjwithinstats(data = d8, dep1 = "Pre", dep2 = "Post", clinicalpreset = pr))
    expect_match(jw_val_strip_html(r_pr$warnings$content), "guidance only", fixed = TRUE)
  }

  # IR-08a: weightsSupport = 'none' prevents jmvcore:::expandWeights from dropping/cloning fractional weights
  d_wt <- d8
  attr(d_wt, "jmv-weights") <- c(0.4, 0.4, 0.4, 2.2, 2.2, 2.2, 1.2, 1.2)
  tb_wt <- suppressWarnings(ClinicoPath::jjwithinstats(
    data = d_wt, dep1 = "Pre", dep2 = "Post", pairedEffects = TRUE, pairedCIMethod = "standard"
  ))$pairedChanges$asDF
  expect_equal(tb_wt$pairs[1], 8L)
  expect_equal(tb_wt$estimate[1], 4.0, tolerance = 1e-12)

  # IR-08b: default run (pairedEffects = FALSE) states independent-case requirement in visible panels
  r_def <- suppressWarnings(ClinicoPath::jjwithinstats(data = d8, dep1 = "Pre", dep2 = "Post"))
  expect_match(jw_val_strip_html(r_def$interpretation$content), "independent case", fixed = TRUE)

  # IR-10a: ggpubrPlotType = 'paired' draws visible trajectory lines at default settings
  skip_if_not_installed("ggpubr")
  gg_p <- jw_val_render_ggpubr(d8, dep1 = "Pre", dep2 = "Post", addGGPubrPlot = TRUE, ggpubrPlotType = "paired")
  b_p  <- ggplot2::ggplot_build(gg_p$plot)
  ln_i <- which(vapply(gg_p$plot$layers, function(l) inherits(l$geom, "GeomLine") || inherits(l$geom, "GeomPath"), logical(1)))
  expect_true(length(ln_i) > 0L && !all(is.na(b_p$data[[ln_i[1]]]$colour)))

  # IR-10b: .a.yaml does not claim unimplemented grouped_ggwithinstats wrapper
  a_yaml <- paste(readLines(testthat::test_path("..", "..", "jamovi", "jjwithinstats.a.yaml"), warn = FALSE), collapse = "\n")
  expect_false(grepl("grouped_ggwithinstats", a_yaml, fixed = TRUE))
})

test_that("Security G1: asSource() escapes character options and drops undeclared names and list values", {
  df <- data.frame(a = c(1, 2, 3, 4), b = c(2, 3, 4, 5))
  parse_matched <- function(src) {
    ex <- parse(text = src)
    expect_length(ex, 1L)
    match.call(ClinicoPath::jjwithinstats, ex[[1]])
  }

  # Free-text OptionString quote-breaking, backslash, and newline payloads
  payload <- 'x", k = {print(1); 2}, xtitle = "y'
  opts1 <- jjwithinstatsOptions$new(dep1 = "a", dep2 = "b", mytitle = payload, pairedUnits = "u\\\n\"z")
  mc1 <- parse_matched(jjwithinstatsClass$new(options = opts1, data = df)$asSource())
  expect_identical(mc1$mytitle, payload)
  expect_identical(mc1$pairedUnits, "u\\\n\"z")
  expect_null(mc1$k)
  expect_null(mc1$xtitle)

  # .omv-style injected string on OptionList and OptionInteger
  opts2 <- jjwithinstatsOptions$new(dep1 = "a", dep2 = "b")
  opts2$.__enclos_env__$private$.options$typestatistics$.__enclos_env__$private$.value <- payload
  opts2$.__enclos_env__$private$.options$k$.__enclos_env__$private$.value <- payload
  mc2 <- parse_matched(jjwithinstatsClass$new(options = opts2, data = df)$asSource())
  expect_identical(mc2$typestatistics, payload)
  expect_identical(mc2$k, payload)
  expect_null(mc2$xtitle)

  # Undeclared option name and list value injected via .omv
  opts3 <- jjwithinstatsOptions$new(dep1 = "a", dep2 = "b")
  opts3$.addOption(jmvcore:::Option$new('k = {print(1); 2}, xtitle', "val"))
  bad_list <- stats::setNames(list(1), 'a = 1), k = {print(1); 2}, xtitle = list(b')
  opts3$.__enclos_env__$private$.options$mytitle$.__enclos_env__$private$.value <- bad_list
  mc3 <- parse_matched(jjwithinstatsClass$new(options = opts3, data = df)$asSource())
  expect_null(mc3$k)
  expect_null(mc3$mytitle)
  expect_null(mc3$xtitle)
})

test_that("Security I5: .prepareData() invalidates cached skewness warning when typestatistics changes", {
  d_skew <- data.frame(
    Pre  = c(10, 10, 10, 10, 10, 10, 10, 10, 10, 10),
    Post = c(10, 10, 10, 10, 10, 10, 10, 10, 11, 200)
  )
  opts <- jjwithinstatsOptions$new(dep1 = "Pre", dep2 = "Post", typestatistics = "parametric")
  an <- jjwithinstatsClass$new(options = opts, data = d_skew)
  an$run()
  expect_match(jw_val_strip_html(an$results$warnings$content), "Skewed Data Detected", fixed = TRUE)

  # Switch typestatistics on the same R6 instance and re-run
  opts$.__enclos_env__$private$.options$typestatistics$.__enclos_env__$private$.value <- "nonparametric"
  an$run()
  expect_false(grepl("Skewed Data Detected", jw_val_strip_html(an$results$warnings$content), fixed = TRUE))
})
